package qa.architecture;
import application.save.GameSaveService; import domain.save.*; import domain.save.snapshot.*; import infrastructure.save.LocalJsonSaveRepository; import java.nio.file.*; import java.util.*;
public final class CanonicalSaveRoundTripVerification {
 @org.junit.jupiter.api.Test
    @org.junit.jupiter.api.Tag("architecture")
        void verifiesCanonicalContract() throws Exception{Path dir=Files.createTempDirectory("lim-save-m491-");try{var repo=new LocalJsonSaveRepository(dir);var service=new GameSaveService(repo);GameSaveSnapshot expected=new GameSaveSnapshot(GameSaveSnapshot.CURRENT_SCHEMA_VERSION,new CharacterSnapshot("kenan","Kenan","HOMBRE","INDOMITO","Guerrero de Ébano",131,10,10,Map.of()),new CombatSnapshot(false,Set.of(),Set.of(),Map.of()),new InventorySnapshot(List.of(),Map.of(),Map.of(),Map.of(),Set.of()),new MasterySnapshot(Set.of(),Set.of(),Set.of(),Set.of(),"","",""),new WorldSnapshot(0,Map.of(),Map.of()),new SurvivalSnapshot(10,10,0,0),new TransportSnapshot("",0,0,0,0,false),new NarrativeSnapshot("MASCULINE","",Set.of(),Map.of()),new ProfileReference("default-profile",0));SaveSlot wake=service.saveWake("kenan",1,expected);org.junit.jupiter.api.Assertions.assertTrue(repo.read(wake.id()).equals(expected),"El wake save debe guardar snapshot real.");SaveSlot quick1=service.saveQuick("kenan",expected);SaveSlot quick2=service.saveQuick("kenan",expected);org.junit.jupiter.api.Assertions.assertTrue(quick1.id().equals(quick2.id()),"El quicksave debe sobrescribir una única ranura.");org.junit.jupiter.api.Assertions.assertTrue(repo.listForPersona("kenan").size()==2,"Sólo deben existir wake + quicksave en esta verificación.");}finally{try(var stream=Files.walk(dir)){stream.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(Exception ignored){}});}}}
 
}
